import { join } from 'node:path'
import type { Context } from '@deepseek-ai/cordis'
// Type-only: pulls in the `connection/request` Events augmentation (DSH
// ≥ 0.1.6-alpha.2) so the bridge wall below typechecks. Erased at build.
import type {} from '@deepseek-ai/dsh-client-connection'
import type { WebRoute } from '@deepseek-ai/dsh-host-webserver'
import type { Config } from './config.ts'
import { Config as ConfigSchema } from './config.ts'
import { SessionStore } from './session.ts'
import { OwnershipIndex } from './ownership.ts'
import { TrustedHosts } from './hosts.ts'
import { DefaultWorkspaceSetting } from './workspace-setting.ts'
import { BooleanSetting } from './boolean-setting.ts'
import { applyWithRetry, RemoteWebUiCompat, type RemoteWebUiCompatDeps } from './remote-web-ui-compat.ts'
import { createGatewayHandler } from './gateway.ts'
import { createApiBridgeAuth } from './api-bridge-auth.ts'
import { installAdmitShadow, installDispatchShadows, type DispatchGuardDeps } from './dispatch-guard.ts'
import { WIRE_SURFACE_DSH_VERSION } from './api-filter.ts'
import { DefaultWorkspaceProvisioner, type WorkspaceRegistryLike } from './provision.ts'
import { createHostSessionApi, createHostSessionSource, tryGetService } from './host-session-access.ts'
import { probeOwnedSessionIds } from './bridge-list-filter.ts'
import { renderLoginPage } from './login-page.ts'
import { createAdminSso } from './admin-sso.ts'
import { provideWebRuntime, resolveDistIndex } from './web-runtime.ts'
import { resolveDshHome } from './http-json.ts'
import { deriveCapabilities } from './capabilities.ts'

/** Stable Cordis plugin name. */
export const name = 'dsh-login'

/** Hard dependency: the DSH web server. */
export const inject = ['webServer']

export { ConfigSchema as Config }

// Compatibility seam (option A, DSH ≥ 0.1.5-alpha.1): the REMOTE-layer
// per-user isolation guard. Re-exported from the host bundle so a deployment
// that wants per-user isolation can import `wrapRemoteGateway` /
// `createRemoteIsolation` FROM THIS PACKAGE and compose them over the native
// `typertGateway` (see docs/verify-option-A.md §B). Note: this is a
// composition primitive, NOT a runtime re-provide — dsh-login cannot
// hot-swap the live `typertGateway` service (duplicate-service error).
export { wrapRemoteGateway, createRemoteIsolation } from './remote-guard.ts'
export type {
  RemoteGateway,
  RemoteInvokeRequest,
  GuardUser,
  UserResolver,
  OwnedPredicate,
} from './remote-guard.ts'
// Deployment-side composition glue (option B): helper + types for wrapping a
// native `typertGateway` row with dsh-login's per-user isolation guard, keyed
// to the ownership sidecar dsh-login publishes as the `dshLoginOwnership`
// service below (see docs/compose-guard.md).
export {
  DSH_LOGIN_OWNERSHIP_SERVICE,
  createDshLoginIsolation,
  composeGuardedGateway,
  composeDshLoginGuard,
  getDshLoginOwnership,
} from './glue.ts'
export type { DshLoginIsolationDeps, WrappedRemoteGateway } from './glue.ts'

/**
 * Register the multi-user authentication gateway on the web server:
 *
 * - Admin SSO login/callback and a DSH-owned HttpOnly session.
 * - The identity-aware `/api` carrier takeover (`createConnectionPlugin`)
 *   mounted as a child plugin, and the OwnershipIndex sidecar with a
 *   teardown flush so pending ownership writes reach disk on stop/update.
 *
 * All route disposers are owned by the plugin fiber via ctx.effect for clean
 * teardown on stop/update/undefine. dsh-login takes over the webRuntime
 * service and the fallback seat from dsh-web-app's web-runtime row (which
 * the shipped cordis.patch.yml disables) and serves the frontend dist
 * through the authenticated gateway.
 */
export function apply(ctx: Context, config: Config): void {
  if (!config.enabled) return
  const dataDir = config.dataDir === '' ? join(resolveDshHome(), '.dsh-login') : config.dataDir
  // Admin refresh tokens stay memory-only, so DSH sessions cannot outlive a Host restart.
  const store = new SessionStore(config.sessionTtl)
  // Keep the username-keyed sidecar untouched; the Admin-ID index starts fresh.
  const ownership = new OwnershipIndex(join(dataDir, 'ownership-v2.json'))
  const hosts = new TrustedHosts(join(dataDir, 'trusted-hosts.json'))
  // The persisted workspace setting starts from config.defaultWorkspace and is
  // read by the provisioner for each request.
  const defaultWorkspaceSetting = new DefaultWorkspaceSetting(join(dataDir, 'settings.json'), config.defaultWorkspace)
  // The persisted "remote-web-ui 兼容" setting starts from config and, when on,
  // dsh-login
  // writes @linxin666/dsh-remote-web-ui's requirePairingForLan to false so
  // non-loopback (public FRP) desktop traffic rides dsh-login's /api channel
  // instead of remote-web-ui's device-pairing gate. No-op if remote-web-ui is
  // not installed. The remote-web-ui plugin reads its own setting per request.
  const remoteWebUiSetting = new BooleanSetting(join(dataDir, 'settings-remote-web-ui.json'), config.remoteWebUiCompat)
  const remoteWebUiCompat = new RemoteWebUiCompat({
    getSettings: () => ctx.get('settings') as unknown as ReturnType<RemoteWebUiCompatDeps['getSettings']>,
  })
  const distIndex = config.distIndex === '' ? resolveDistIndex() : config.distIndex
  const gatewayConfig = { ...config, distIndex }
  const publicBaseUrl = config.publicBaseUrl || ctx.webServer.getOrigin()
  const adminSso = createAdminSso({
    adminBaseUrl: config.adminBaseUrl.replace(/\/+$/, ''),
    clientId: config.adminClientId,
    redirectUri: `${publicBaseUrl.replace(/\/+$/, '')}/api/auth/callback`,
    sessionTtl: config.sessionTtl,
    autoTrustHosts: config.autoTrustHosts,
    hosts,
  }, store)

  // Capture the webRuntime LAN literals so the /api takeover trusts the
  // bound LAN addresses automatically (the shipped connection row read them
  // from webRuntime too; dsh-login's own fence used to see only the static
  // config list, which is why LAN IPs and frp public hosts needed hand-listing).
  const runtime = config.takeOverWebRuntime ? provideWebRuntime(ctx, config.trustedHosts) : undefined

  // Per-user default-workspace provisioning: the provisioner resolves the
  // host session surface lazily (sessionController first, typertGateway as
  // fallback) and the durable workspace registry lazily, because neither
  // service is guaranteed to be registered at dsh-login's apply time. It
  // reads the persisted defaultWorkspace setting for each request.
  const workspaceRoot = config.workspaceRoot === '' ? join(resolveDshHome(), 'workspaces') : config.workspaceRoot
  const provisioner = new DefaultWorkspaceProvisioner({
    workspaceRoot,
    getApi: createHostSessionApi(ctx),
    ownership,
    getRegistry: () => tryGetService<WorkspaceRegistryLike>(ctx, 'workspaceRegistry'),
    enabled: () => defaultWorkspaceSetting.get(),
  })
  // Publish the live ownership sidecar as a service so a deployment row
  // (docs/compose-guard.md) can compose dsh-login's isolation guard over the
  // native typertGateway without reaching into dsh-login internals. Declared
  // in the composing row's `inject` so the composition runs after dsh-login.
  ctx.provide('dshLoginOwnership', ownership)

  const loginPageRoute: WebRoute = {
    kind: 'exact',
    path: '/login',
    handler: async (_req, res) => {
      const html = renderLoginPage()
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' })
      res.end(html)
    },
  }

  const gatewayHandler = createGatewayHandler(ctx, gatewayConfig, store, adminSso.userInfo)

  ctx.effect(() => ctx.webServer.register(loginPageRoute), 'dsh-login: /login')
  for (const route of adminSso.routes) {
    ctx.effect(() => ctx.webServer.register(route), `dsh-login: ${route.path}`)
  }
  ctx.provide('dshLoginAuth', {
    accessToken: adminSso.accessToken,
    refreshAccessToken: adminSso.refreshAccessToken,
    isUserAuthenticated: adminSso.isUserAuthenticated,
    userInfo: adminSso.userInfo,
    permissionsForUser: (userId: string) => store.permissionsForUser(userId),
    resolveAgentUserId: (agentSessionId: string) => ownership.lookup(agentSessionId),
    currentUser: adminSso.currentUser,
    onLogin: adminSso.onLogin,
    onLogout: adminSso.onLogout,
  })
  // Boot-time application of the remote-web-ui compatibility toggle. Deferred
  // so it never blocks startup; applyWithRetry keeps retrying a few hundred ms
  // in case remote-web-ui's settings namespace registers after dsh-login does.
  const bootCompat = applyWithRetry(remoteWebUiCompat, remoteWebUiSetting.get(), config.remoteWebUiPublicBaseUrl)
  void bootCompat
  // The gateway claims the fallback seat (not prefix /) because the
  // WebServer's prefix match only catches the exact path '/' for a '/'
  // prefix. The fallback catches everything no named route claims.
  ctx.effect(() => ctx.webServer.registerFallback(gatewayHandler), 'dsh-login: gateway fallback')

  // DSH ≥ 0.1.6-alpha.2: the native connection row fires `connection/request`
  // on its shared /api route before bridging. dsh-login registers a wall
  // (default on, config.apiBridgeAuth) so /api requires a live dsh-login
  // session — logout/expiry actually revokes the bridge even though the
  // process-wide browser-auth cookie persists. `global: true` keeps the
  // listener firing regardless of any context filter at the emit site; on
  // DSH < 0.1.6-alpha.2 the event never fires and this is a harmless no-op.
  if (config.apiBridgeAuth) {
    // Diagnostics for a stale allow-list: a denial of a method this build does
    // not know about means upstream renamed something (the issue #4 failure
    // mode). Warn once per method so a rename is visible in the host log
    // instead of only in the user's browser console.
    const reported = new Set<string>()
    const reportUnknownMethod = (method: string, username: string): void => {
      if (reported.has(method)) return
      reported.add(method)
      const message = `dsh-login: /api/${method} was denied for '${username}' but is not part of the DSH ${WIRE_SURFACE_DSH_VERSION} wire surface this build knows — upstream may have renamed it; refresh src/api-filter.ts (node scripts/dump-wire-surface.mjs)`
      const logger = (ctx as unknown as { logger?: { warn?: (msg: string) => void } }).logger
      if (typeof logger?.warn === 'function') logger.warn(message)
      else console.warn(message)
    }
    // Owned-set resolution for response filtering: best-effort probe over the
    // sidecar closure plus the caller's live session list. A failed probe
    // degrades to sidecar-only filtering (or none when the sidecar is empty).
    const ownedProvider = (username: string) => probeOwnedSessionIds(username, ownership, createHostSessionSource(ctx))
    ctx.effect(
      () => ctx.on('connection/request', createApiBridgeAuth({
        store,
        ownership,
        quietDenials: config.quietDenials,
        ownedProvider,
        provisioner,
        onUnknownMethod: reportUnknownMethod,
      }), { global: true }),
      'dsh-login: /api bridge auth wall',
    )
  }

  // Issue #11: streaming methods (`workspace.follow`, `session.follow`, …)
  // ride the Remote stream mux WebSocket, which the bridge wall above never
  // sees. The dispatch-seam guard shadows the connection service's `admit`
  // (so the mux upgrade requires a live dsh-login session too) and the
  // gateway's `dispatchRpc` / `openWireStream` (so tagged browser peers are
  // checked against the wire surface and per-id ownership, and
  // `workspace.follow` trees are filtered per user). Untagged peers —
  // launch-token CLI/SDK sessions and host-internal callers — pass through
  // untouched. Same feature gate as the wall: this is the isolation
  // boundary, not a standalone feature.
  if (config.apiBridgeAuth) {
    const warnLog = (message: string): void => {
      const logger = (ctx as unknown as { logger?: { warn?: (msg: string) => void } }).logger
      if (typeof logger?.warn === 'function') logger.warn(message)
      else console.warn(message)
    }
    const guardDeps = {
      store,
      ownership,
      sessionSource: () => createHostSessionSource(ctx),
    }
    ctx.inject(['connection', 'typertGateway'], (fork) => {
      fork.effect(() => {
        const uninstallAdmit = installAdmitShadow(fork.connection, guardDeps, warnLog)
        const uninstallDispatch = installDispatchShadows(tryGetService(fork, 'typertGateway'), guardDeps, warnLog)
        return () => {
          uninstallAdmit()
          uninstallDispatch()
        }
      }, 'dsh-login: dispatch-seam guard')
    })
  }

  // Per-identity capability baseline, injected at render time. index-inject
  // fires before any specific user's request, so this declares the ordinary-
  // user surface as a static, safe default (the common case for dsh-login);
  // clients that need the exact identity (an admin, a special account) fetch
  // GET /api/auth/capabilities, which is authoritative. UI-plugin boot code
  // can read window.__DSH_SESSION__ to skip features the current user cannot
  // use instead of probing (and being denied on) them.
  const cap = deriveCapabilities({ username: '', isAdmin: false, permissions: [] })
  const sessionBaselineScript = `window.__DSH_SESSION__={username:null,isAdmin:false,capabilities:${JSON.stringify(cap)}};`
  ctx.effect(() => ctx.on('webserver/index-inject', (table: Array<{ kind: string; placement: string; text: string }>) => {
    table.push({ kind: 'script', placement: 'head', text: sessionBaselineScript })
  }), 'dsh-login: capability baseline injection')

  // Teardown: flush any pending ownership-index / trusted-hosts writes to
  // disk. Returning the Promise lets Cordis await it on stop so a freshly
  // learned host (debounce still pending) is not dropped (review #3).
  ctx.effect(() => () => {
    adminSso.clear()
    return Promise.all([store.flush(), ownership.flush(), hosts.flush(), defaultWorkspaceSetting.flush(), remoteWebUiSetting.flush()])
  }, 'dsh-login: sessions + ownership + hosts + settings flush')
}
