  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 DSH</title><body style="font:16px system-ui;max-width:520px;margin:15vh auto;padding:24px;color:#172033"><h1>登录 DSH</h1><p>使用 Admin 账号继续。</p><p style="display:flex;flex-wrap:wrap;gap:12px"><a href="/api/auth/login" style="display:inline-block;padding:12px 20px;background:#2458d3;color:white;text-decoration:none;border-radius:6px">快捷登录</a><a href="/api/auth/login?mode=password" style="display:inline-block;padding:12px 20px;border:1px solid #2458d3;color:#2458d3;text-decoration:none;border-radius:6px">账号密码登录</a></p><p style="font-size:14px;color:#667085">账号密码登录会打开 Admin 登录页，登录成功后自动返回 DSH。</p></body></html>`
